import{_ as l,a0 as r,w as o,s as p,ao as g,I as n,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"管理大型 Postgres 資料庫的 3 個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"管理大型 Postgres 資料庫的 3 個技巧 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理大型 Postgres 資料庫的 3 個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理大型 Postgres 資料庫的 3 個技巧 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230228.2 ⭐️ 3 tips to manage large Postgres databases","title":"管理大型 Postgres 資料庫的 3 個技巧","tag":"202303","desc":""},"relativePath":"202303/20230228.2 ⭐️ 3 tips to manage large Postgres databases.md","filePath":"[post].md"}'),d={name:"202303/20230228.2 ⭐️ 3 tips to manage large Postgres databases.md"};function h(k,s,b,c,u,m){const t=r("Link");return o(),p("div",null,[s[15]||(s[15]=g('<h1 id="管理大型-postgres-資料庫的-3-個技巧" tabindex="-1">管理大型 Postgres 資料庫的 3 個技巧 <a class="header-anchor" href="#管理大型-postgres-資料庫的-3-個技巧" aria-label="Permalink to “管理大型 Postgres 資料庫的 3 個技巧”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/06/113049bkunsxun1clzuca8.jpg" alt=""></p><blockquote><p>在處理龐大的資料庫時，請嘗試這些方便的解決方案，以解決常見的問題。</p></blockquote><p>關係型資料庫 PostgreSQL（也被稱為 Postgres）已經越來越流行，全球各地的企業和公共部門都在使用它。隨着這種廣泛的採用，資料庫已經變得比以前更大了。在 Crunchy Data，我們經常與 20TB 以上的資料庫打交道，而且我們現有的資料庫還在繼續增長。我的同事 David Christensen 和我收集了一些關於管理擁有巨大表的資料庫的技巧。</p><h3 id="大表" tabindex="-1">大表 <a class="header-anchor" href="#大表" aria-label="Permalink to “大表”">​</a></h3><p>生產資料庫通常由許多具有不同數據、大小和模式的表組成。常見的情況是，最終有一個巨大的、無序的資料庫表，遠遠大於你資料庫中的任何其他表。這個表經常存儲活動日誌或有時間戳的事件，而且對你的應用或用户來説是必要的。</p><p>真正的大表會因為很多原因造成挑戰，但一個常見的原因是鎖。對錶的定期維護往往需要鎖，但對大表的鎖可能會使你的應用癱瘓，或導致堵塞和許多令人頭痛的問題。我有一些做基本維護的技巧，比如添加列或索引，同時避免長期運行的鎖。</p><p><strong>添加索引的問題</strong>：在創建索引的過程中鎖住表。如果你有一個龐大的表，這可能需要幾個小時。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE INDEX ON customers (last_name)</span></span></code></pre></div><p><strong>方案</strong>：使用 <code>CREATE INDEX CONCURRENTLY</code> 功能。這種方法將索引創建分成兩部分，一部分是短暫的鎖定，以創建索引，立即開始跟蹤變化，但儘量減少應用阻塞，然後是完全建立該索引，之後查詢可以開始使用它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE INDEX CONCURRENTLY ON customers (last_name)</span></span></code></pre></div><h3 id="添加列" tabindex="-1">添加列 <a class="header-anchor" href="#添加列" aria-label="Permalink to “添加列”">​</a></h3><p>在資料庫的使用過程中，添加列是一個常見的請求，但是對於一個巨大的表來説，這可能是很棘手的，同樣是由於鎖的問題。</p><p><strong>問題</strong>：當你添加一個新的默認值為一個函數的列時，Postgres 需要重寫表。對於大表，這可能需要幾個小時。</p><p><strong>方案</strong>：將操作拆分為多條基本語句，總效果一致，但控制鎖的時間。</p><p>添加列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE all_my_exes ADD COLUMN location text</span></span></code></pre></div><p>添加默認值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE all_my_exes ALTER COLUMN location SET DEFAULT texas()</span></span></code></pre></div><p>使用 <code>UPDATE</code> 來添加默認值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UPDATE all_my_exes SET location = DEFAULT</span></span></code></pre></div><h3 id="添加約束條件" tabindex="-1">添加約束條件 <a class="header-anchor" href="#添加約束條件" aria-label="Permalink to “添加約束條件”">​</a></h3><p><strong>問題</strong>: 你想添加一個用於數據驗證的檢查約束。但是如果你使用直接的方法來添加約束，它將鎖定表，同時驗證表中的所有現有數據。另外，如果在驗證的任何時候出現錯誤，它將回滾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE favorite_bands ADD CONSTRAINT name_check CHECK (name = &#39;Led Zeppelin&#39;)</span></span></code></pre></div><p><strong>方案</strong>：告訴 Postgres 這個約束，但不要驗證它。在第二步中進行驗證。這將在第一步中進行短暫的鎖定，確保所有新的/修改過的行都符合約束條件，然後在另一步驟中進行驗證，以確認所有現有的數據都通過約束條件。</p><p>告訴 Postgres 這個約束，但不要強制執行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE favorite_bands ADD CONSTRAINT name_check CHECK (name = &#39;Led Zeppelin&#39;) NOT VALID</span></span></code></pre></div><p>然後在創建後<strong>驗證</strong>它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE favorite_bands VALIDATE CONSTRAINT name_check</span></span></code></pre></div><h3 id="想了解更多" tabindex="-1">想了解更多？ <a class="header-anchor" href="#想了解更多" aria-label="Permalink to “想了解更多？”">​</a></h3><p>David Christensen 和我將在 3 月 9 號到 10 到在加州帕薩迪納參加 SCaLE 的 Postgres Days。很多來自 Postgres 社區的優秀人士也會在那裏。加入我們吧！</p><hr>',32)),n("p",null,[s[1]||(s[1]=e("via: ",-1)),a(t,{href:"https://opensource.com/article/23/2/manage-large-postgres-databases"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/23/2/manage-large-postgres-databases",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=e("作者：",-1)),a(t,{href:"https://opensource.com/users/elizabethchristensencrunchydatacom"},{default:i(()=>[...s[2]||(s[2]=[e("Elizabeth Garrett Christensen",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(t,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const x=l(d,[["render",h]]);export{C as __pageData,x as default};
